use super::{Args, Failures};
use crate::git::Repo;
use crate::policy::{self, CommitRules};
use anyhow::{Result, bail};

const ATTRIBUTION: &[&str] = &[
    "co-authored-by:",
    "assisted-by:",
    "generated with",
    "generated by",
    "noreply@anthropic.com",
    "\u{1f916}",
];

const SKIP_MARKERS: &[&str] = &[
    "[skip ci]",
    "[ci skip]",
    "[no ci]",
    "[skip actions]",
    "[actions skip]",
    "skip-checks: true",
    "skip-checks:true",
];

fn clean(message: &str) -> String {
    message
        .lines()
        .take_while(|line| !line.starts_with("# ------------------------ >8"))
        .filter(|line| !line.starts_with('#'))
        .collect::<Vec<_>>()
        .join("\n")
        .trim()
        .to_owned()
}

pub fn problems(raw: &str, rules: &CommitRules) -> Vec<String> {
    let message = clean(raw);
    let subject = message.lines().next().unwrap_or_default();
    let mut found = Vec::new();
    match subject.split_once(": ") {
        Some((head, summary)) if !summary.trim().is_empty() => {
            let head = head.trim_end_matches('!');
            match head.split_once('(') {
                Some((kind, scope)) if scope.ends_with(')') => {
                    let scope = scope.trim_end_matches(')');
                    if !rules.types.iter().any(|t| t == kind) {
                        found.push(format!(
                            "type \"{kind}\" is not one of {}",
                            rules.types.join(", ")
                        ));
                    }
                    if !rules.scopes.iter().any(|s| s == scope) {
                        found.push(format!(
                            "scope \"{scope}\" is not one of {}",
                            rules.scopes.join(", ")
                        ));
                    }
                }
                _ => found.push("the subject has no (<scope>)".to_owned()),
            }
        }
        _ => found.push("the subject is not \"<type>(<scope>): <summary>\"".to_owned()),
    }
    let lower = raw.to_lowercase();
    if let Some(marker) = ATTRIBUTION.iter().find(|m| lower.contains(*m)) {
        found.push(format!("it holds an attribution line ({marker})"));
    }
    if let Some(marker) = SKIP_MARKERS.iter().find(|m| lower.contains(*m)) {
        found.push(format!("it holds a CI skip marker ({marker})"));
    }
    found
}

fn report(label: &str, message: &str, rules: &CommitRules) -> Failures {
    problems(message, rules)
        .into_iter()
        .map(|problem| {
            format!(
                "Commit message {label}: {problem}. Use \"<type>(<scope>): <summary>\" with no co-author or attribution lines."
            )
        })
        .collect()
}

pub fn commit_message(repo: &Repo, args: &Args) -> Result<Failures> {
    let rules = policy::layout(repo)?.commits;
    if let Some(file) = args.value("--file") {
        let message = std::fs::read_to_string(&file)?;
        return Ok(report("being written", &message, &rules));
    }
    let Some(range) = args.value("--range") else {
        bail!("commit-message needs --file <path> or --range <base>..<head>");
    };
    let mut failures = Failures::new();
    let listing = repo.git(&["rev-list", "--no-merges", &range])?;
    for commit in listing.lines().filter(|l| !l.is_empty()) {
        let message = repo.git(&["log", "-1", "--format=%B", commit])?;
        failures.extend(report(&commit[..12.min(commit.len())], &message, &rules));
    }
    Ok(failures)
}

#[cfg(test)]
mod tests {
    use super::problems;
    use crate::policy::CommitRules;

    fn rules() -> CommitRules {
        CommitRules {
            types: vec!["feat".to_owned(), "fix".to_owned()],
            scopes: vec!["app".to_owned(), "saves".to_owned()],
        }
    }

    #[test]
    fn accepts_conventional_subject_with_scope() {
        assert!(
            problems(
                "fix(saves): refuse unknown save versions\n\nBody.\n",
                &rules()
            )
            .is_empty()
        );
        assert!(problems("feat(app)!: replace the main window\n", &rules()).is_empty());
    }

    #[test]
    fn rejects_missing_type_scope_or_unknown_scope() {
        assert!(!problems("refuse unknown versions", &rules()).is_empty());
        assert!(!problems("fix: refuse unknown versions", &rules()).is_empty());
        assert!(!problems("fix(auth): refuse expired tokens", &rules()).is_empty());
    }

    #[test]
    fn rejects_attribution_and_skip_markers() {
        let coauthor = "fix(app): x\n\nCo-Authored-By: Someone <a@b.c>\n";
        assert!(
            problems(coauthor, &rules())
                .iter()
                .any(|p| p.contains("attribution"))
        );
        assert!(
            problems("fix(app): x [skip ci]", &rules())
                .iter()
                .any(|p| p.contains("skip"))
        );
    }

    #[test]
    fn ignores_git_comment_lines_for_the_subject() {
        assert!(problems("fix(app): x\n# Please enter the commit message\n", &rules()).is_empty());
    }

    #[test]
    fn markers_on_hash_lines_still_fail() {
        assert!(!problems("fix(app): x\n\n# [skip ci]\n", &rules()).is_empty());
        assert!(!problems("fix(app): x\n\n#Co-Authored-By: A <a@b.c>\n", &rules()).is_empty());
    }
}
